materials.fragmentShader:
#define STANDARD
#ifdef PHYSICAL
	#define IOR
	#define USE_SPECULAR
#endif
uniform vec3 diffuse;
uniform vec3 emissive;
uniform float roughness;
uniform float metalness;
uniform float opacity;
#ifdef IOR
	uniform float ior;
#endif
#ifdef USE_SPECULAR
	uniform float specularIntensity;
	uniform vec3 specularColor;
	#ifdef USE_SPECULAR_COLORMAP
		uniform sampler2D specularColorMap;
	#endif
	#ifdef USE_SPECULAR_INTENSITYMAP
		uniform sampler2D specularIntensityMap;
	#endif
#endif
#ifdef USE_CLEARCOAT
	uniform float clearcoat;
	uniform float clearcoatRoughness;
#endif
#ifdef USE_DISPERSION
	uniform float dispersion;
#endif
#ifdef USE_RETROREFLECTION
	uniform float retroreflectivity;
#endif
#ifdef USE_IRIDESCENCE
	uniform float iridescence;
	uniform float iridescenceIOR;
	uniform float iridescenceThicknessMinimum;
	uniform float iridescenceThicknessMaximum;
#endif
#ifdef USE_SHEEN
	uniform vec3 sheenColor;
	uniform float sheenRoughness;
	#ifdef USE_SHEEN_COLORMAP
		uniform sampler2D sheenColorMap;
	#endif
	#ifdef USE_SHEEN_ROUGHNESSMAP
		uniform sampler2D sheenRoughnessMap;
	#endif
#endif
#ifdef USE_ANISOTROPY
	uniform vec2 anisotropyVector;
	#ifdef USE_ANISOTROPYMAP
		uniform sampler2D anisotropyMap;
	#endif
#endif
varying vec3 vViewPosition;
#include <common>
        uniform sampler2D tGrassC, tGrassN, tDirtC, tDirtN, tRockC, tRockN, tPebC, tPebN;
        varying vec4 vSplat; varying vec2 vAux; varying vec3 vTW; varying vec3 vTN;
        vec3 tBlendN; float tRough; float tCaust;
        vec4 layerC(sampler2D t, vec2 uv, float far){
          vec4 a = texture2D(t, uv);
          if (far > 0.2) a = mix(a, texture2D(t, uv * 0.21 + 0.37) * vec4(1.04, 1.02, 1.0, 1.0), far * 0.55);
          return a;
        }

#include <dithering_pars_fragment>
#include <color_pars_fragment>
#include <uv_pars_fragment>
#include <map_pars_fragment>
#include <alphamap_pars_fragment>
#include <alphatest_pars_fragment>
#include <alphahash_pars_fragment>
#include <aomap_pars_fragment>
#include <lightmap_pars_fragment>
#include <emissivemap_pars_fragment>
#include <iridescence_fragment>
#include <cube_uv_reflection_fragment>
#include <envmap_common_pars_fragment>
#include <envmap_physical_pars_fragment>
#include <fog_pars_fragment>
#include <lights_pars_begin>
#include <normal_pars_fragment>
#include <lights_physical_pars_fragment>
#include <transmission_pars_fragment>
#include <shadowmap_pars_fragment>
#include <bumpmap_pars_fragment>
#include <normalmap_pars_fragment>
#include <clearcoat_pars_fragment>
#include <iridescence_pars_fragment>
#include <roughnessmap_pars_fragment>
#include <metalnessmap_pars_fragment>
#include <logdepthbuf_pars_fragment>
#include <clipping_planes_pars_fragment>
void main() {
	vec4 diffuseColor = vec4( diffuse, opacity );
	#include <clipping_planes_fragment>
	ReflectedLight reflectedLight = ReflectedLight( vec3( 0.0 ), vec3( 0.0 ), vec3( 0.0 ), vec3( 0.0 ) );
	vec3 totalEmissiveRadiance = emissive;
	#include <logdepthbuf_fragment>

        vec3 wp = vTW; vec3 N = normalize(vTN);
        float camD = length(wp - cameraPosition);
        // mirror pass, far slopes and the riverbed (seen only through tinted, rippled water) take the cheap path
        bool cheap = uReflect > 0.5 || camD > 260.0 || wp.y < -0.35;
        float far = cheap ? 0.0 : smoothstep(18.0, 70.0, camD);
        bool detailN = !cheap && camD < 75.0;
        vec4 w = vSplat;
        float macro = vnoise(wp.xz * 0.045) * 0.65 + vnoise(wp.xz * 0.11) * 0.35;
        vec2 uvG = wp.xz / 3.2, uvD = wp.xz / 4.1, uvP = wp.xz / 2.3;
        vec4 cG = vec4(0.0), cD = vec4(0.0), cP = vec4(0.0), cR = vec4(0.0);
        if (w.x > 0.004) cG = layerC(tGrassC, uvG, far);
        if (w.y > 0.004) cD = layerC(tDirtC, uvD, far);
        if (w.w > 0.004) cP = layerC(tPebC, uvP, far);
        vec3 bw = pow(abs(N), vec3(4.0)); bw /= (bw.x + bw.y + bw.z);
        float rs = 1.0 / 7.5;
        if (w.z > 0.004) {
          if (cheap) cR = texture2D(tRockC, (abs(N.x) > abs(N.z) ? wp.zy : wp.xy) * rs);
          else {
            // triplanar, skipping projections that barely contribute
            if (bw.x > 0.04) cR += layerC(tRockC, wp.zy * rs, far) * bw.x;
            if (bw.y > 0.04) cR += layerC(tRockC, wp.xz * rs, far) * bw.y;
            if (bw.z > 0.04) cR += layerC(tRockC, wp.xy * rs, far) * bw.z;
            cR /= max(bw.x * step(0.04, bw.x) + bw.y * step(0.04, bw.y) + bw.z * step(0.04, bw.z), 1e-3);
          }
        }
        float hG = dot(cG.rgb, vec3(0.33)), hD = dot(cD.rgb, vec3(0.33)), hR = dot(cR.rgb, vec3(0.33)), hP = dot(cP.rgb, vec3(0.33));
        vec4 hw = w + vec4(hG, hD, hR, hP) * 0.55 + vec4(macro * 0.25, (1.0 - macro) * 0.2, 0.0, 0.0);
        float mx = max(max(hw.x, hw.y), max(hw.z, hw.w));
        vec4 bl = max(hw - (mx - 0.22), 0.0) * step(0.004, w);
        bl /= max(bl.x + bl.y + bl.z + bl.w, 1e-4);
        // the scanned maps are very dark (1-3% linear): lift each layer to a plausible albedo
        vec3 alb = cG.rgb * bl.x * vec3(4.1, 4.6, 3.4) + cD.rgb * bl.y * vec3(4.4, 4.1, 3.8) + cR.rgb * bl.z * vec3(6.6, 7.0, 7.2) + cP.rgb * bl.w * 4.2;
        alb *= mix(vec3(0.82, 0.9, 0.78), vec3(1.12, 1.06, 0.92), macro);
        float forest = smoothstep(90.0, 240.0, camD) * (1.0 - bl.z * 0.7) * smoothstep(3.0, 14.0, wp.y);
        alb = mix(alb, vec3(0.045, 0.07, 0.045) * (0.7 + 0.6 * vnoise(wp.xz * 0.08)), forest * 0.85);
        float wet = smoothstep(0.55, -0.05, wp.y - 0.00);
        alb *= mix(1.0, 0.55, wet);
        alb = mix(alb, alb * vec3(0.75, 0.9, 0.7), smoothstep(0.0, -1.2, wp.y));
        float pet = 0.0;
        if (vAux.y > 0.01) {
          pet = vAux.y * smoothstep(0.62, 0.8, vnoise(wp.xz * 5.3) * 0.6 + vnoise(wp.xz * 13.0) * 0.4 + vAux.y * 0.25);
          alb = mix(alb, vec3(0.93, 0.62, 0.68), pet * 0.8);
        }
        alb *= vAux.x;
        diffuseColor.rgb *= alb;
        tRough = 0.85;
        tBlendN = N;
        if (detailN) {
          vec3 nG = w.x > 0.004 ? texture2D(tGrassN, uvG).xyz : vec3(0.5, 0.5, 0.85);
          vec3 nD = w.y > 0.004 ? texture2D(tDirtN, uvD).xyz : vec3(0.5, 0.5, 0.85);
          vec3 nP = w.w > 0.004 ? texture2D(tPebN, uvP).xyz : vec3(0.5, 0.5, 0.85);
          vec2 dG = (nG.xy * 2.0 - 1.0), dD = (nD.xy * 2.0 - 1.0), dP = (nP.xy * 2.0 - 1.0);
          vec2 flatD = (dG * bl.x + dD * bl.y + dP * bl.w) * (1.0 - far * 0.6);
          tRough = nG.z * bl.x + nD.z * bl.y + nP.z * bl.w + 0.8 * bl.z;
          tBlendN = normalize(vec3(N.x + flatD.x, N.y, N.z + flatD.y));
          if (bl.z > 0.01) {
            vec3 nX = texture2D(tRockN, wp.zy * rs).xyz, nY = texture2D(tRockN, wp.xz * rs).xyz, nZ = texture2D(tRockN, wp.xy * rs).xyz;
            vec2 tx = nX.xy * 2.0 - 1.0, ty = nY.xy * 2.0 - 1.0, tz = nZ.xy * 2.0 - 1.0;
            vec3 nwRock = normalize(bw.x * vec3(N.x, N.y + tx.y, N.z + tx.x) + bw.y * vec3(N.x + ty.x, N.y, N.z + ty.y) + bw.z * vec3(N.x + tz.x, N.y + tz.y, N.z));
            tBlendN = normalize(mix(tBlendN, nwRock, bl.z));
            tRough += (nX.z * bw.x + nY.z * bw.y + nZ.z * bw.z - 0.8) * bl.z;
          }
          tBlendN = normalize(mix(tBlendN, N, pet * 0.6));
        }
        tRough = mix(tRough, 0.25, wet * 0.8);
        // under the surface there is no air-to-stone sheen (water matches the stone's index): matte bed
        tRough = mix(tRough, 1.0, smoothstep(-0.02, -0.15, wp.y));
        // sun caustics dancing on the shallow riverbed (added as extra sunlight, so shadows still hold)
        tCaust = 0.0;
        if (wp.y < 0.02 && uReflect < 0.5 && camD < 120.0) {
          float dep = -wp.y;
          vec2 cp = wp.xz * 0.95;
          float ca = vnoise(cp + vec2(uTime * 0.55, uTime * 0.35));
          float cb = vnoise(cp * 1.6 - vec2(uTime * 0.42, -uTime * 0.3) + ca * 1.8);
          float cc = pow(1.0 - clamp(abs(ca - cb) * 2.4, 0.0, 1.0), 9.0);
          tCaust = cc * exp(-dep * 0.9) * smoothstep(0.0, 0.2, dep);
        }

	#include <color_fragment>
	#include <alphamap_fragment>
	#include <alphatest_fragment>
	#include <alphahash_fragment>
	float roughnessFactor = clamp(tRough * 1.05, 0.2, 1.0);
	#include <metalnessmap_fragment>
	#include <normal_fragment_begin>
	normal = normalize((viewMatrix * vec4(tBlendN, 0.0)).xyz);
	#include <clearcoat_normal_fragment_begin>
	#include <clearcoat_normal_fragment_maps>
	#include <emissivemap_fragment>
	#include <lights_physical_fragment>
	#include <lights_fragment_begin>
	#include <lights_fragment_maps>
	#include <lights_fragment_end>
        reflectedLight.directDiffuse += gSunColor * diffuseColor.rgb * tCaust * 1.3 * (1.0 - 0.5 * smoothstep(0.3, 0.8, uSunDir.y));
        // light reaching the riverbed has already crossed the water column (tinted and dimmed on the way down);
        // without this the shallows glowed cyan under a high sun
        if (vFogWP.y < 0.0) reflectedLight.directDiffuse *= exp(-vec3(0.58, 0.16, 0.24) * 1.4 * (-vFogWP.y) / max(uSunDir.y, 0.2)) * mix(1.0, 0.7, smoothstep(0.3, 0.8, uSunDir.y));
	#include <aomap_fragment>
	vec3 totalDiffuse = reflectedLight.directDiffuse + reflectedLight.indirectDiffuse;
	vec3 totalSpecular = reflectedLight.directSpecular + reflectedLight.indirectSpecular;
	#include <transmission_fragment>
	vec3 outgoingLight = totalDiffuse + totalSpecular + totalEmissiveRadiance;
	#ifdef USE_SHEEN

		outgoingLight = outgoingLight + sheenSpecularDirect + sheenSpecularIndirect;

 	#endif
	#ifdef USE_CLEARCOAT
		float dotNVcc = saturate( dot( geometryClearcoatNormal, geometryViewDir ) );
		vec3 Fcc = F_Schlick( material.clearcoatF0, material.clearcoatF90, dotNVcc );
		outgoingLight = outgoingLight * ( 1.0 - material.clearcoat * Fcc ) + ( clearcoatSpecularDirect + clearcoatSpecularIndirect ) * material.clearcoat;
	#endif
	#include <opaque_fragment>
	#include <tonemapping_fragment>
	#include <colorspace_fragment>
	#include <fog_fragment>
	#include <premultiplied_alpha_fragment>
	#include <dithering_fragment>
}

