materials.vertexShader:
uniform float uTime;
uniform vec3 uSunDir;
uniform vec3 uSunCol;
uniform vec3 uFogCool;
uniform vec3 uFogWarm;
uniform vec4 uFogParams;
uniform vec4 uWind;
uniform float uReflect;
uniform float uMist;
uniform sampler2D uRiverTex;
uniform vec4 uBoat;
uniform mat4 uBoatInv;
uniform vec3 uAmbK;
uniform float uNight, uStorm, uRain, uWet, uFlash, uSunVis, uLampOn;
uniform int uLampN;
uniform vec3 uFlashDir, uMoonDir, uSkyZen, uSkyUp, uCloudLit, uCloudShade, uHorizonGlow, uLampCol;
uniform vec4 uLamps[8];
uniform vec4 uOar;
uniform vec3 uLampC[8];
uniform float uWetBias;     // per-material standing wetness (spray on the boat, the boatman)

// waterline half-beam of the boat hull at normalised length s (0 stern .. 1 bow) — matches boat.js
float boatHalfBeam(float s){
  s = clamp(s, 0.0, 1.0);
  return s < 0.45 ? 0.86 * (1.0 - pow((0.45 - s) / 0.45, 2.2) * 0.42) : 0.86 * pow(max(0.0, 1.0 - pow((s - 0.45) / 0.55, 1.7)), 0.6);
}
// 1 where a world point lies inside the hull's planking (its real cross-section, following the boat's
// bob, pitch and roll), else 0. The floorboards sit below the river's surface, so the water is cut out here.
float boatInside(vec3 wp, float inset){
  vec3 p = (uBoatInv * vec4(wp, 1.0)).xyz;
  float s = p.z / 8.2 + 0.5;
  if (s <= 0.0 || s >= 1.0) return 0.0;
  float k = -0.24 + 0.07 * pow(1.0 - s, 3.0) + 0.64 * pow(s, 3.5), h = 0.5 + 0.16 * pow(1.0 - s, 4.0) + 0.95 * pow(s, 3.2);
  if (p.y < k + inset || p.y > h) return 0.0;
  float b = boatHalfBeam(s), w = b * 0.66 * (1.0 - smoothstep(0.68, 1.0, s) * 0.85);
  float kx = mix(w, b, 0.46) + 0.035, ky = mix(k, h, 0.44);
  float hw = p.y < ky ? mix(w, kx, (p.y - k) / (ky - k)) : mix(kx, b, (p.y - ky) / (h - ky));
  return step(abs(p.x), hw - inset);
}

float hash12(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * .1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }
float hash13(vec3 p3){ p3 = fract(p3 * .1031); p3 += dot(p3, p3.zyx + 31.32); return fract((p3.x + p3.y) * p3.z); }
float vnoise(vec2 p){ vec2 i = floor(p), f = fract(p); vec2 u = f*f*(3.0-2.0*f);
  return mix(mix(hash12(i), hash12(i+vec2(1,0)), u.x), mix(hash12(i+vec2(0,1)), hash12(i+vec2(1,1)), u.x), u.y); }
float fbm3(vec2 p){ return vnoise(p)*0.55 + vnoise(p*2.03+7.1)*0.28 + vnoise(p*4.11-3.7)*0.17; }
// lacy whitewater: coverage 'amt' (0..1) eats into a three-octave cell pattern, so edges break up
float foamLace(vec2 p, float amt){
  float cells = vnoise(p * 2.6) * 0.5 + vnoise(p * 6.3 + 3.1) * 0.3 + vnoise(p * 14.0 - 1.7) * 0.2;
  return smoothstep(0.0, 0.28, amt * 1.1 - (1.0 - cells));
}

// raindrop rings: one drop per cell per layer, each ring expanding and fading on its own clock
vec2 rainRipples(vec2 p){
  vec2 acc = vec2(0.0);
  for (int k = 0; k < 3; k++) {
    float sc = k == 0 ? 1.7 : (k == 1 ? 2.45 : 3.3);
    vec2 q = p * sc + float(k) * 17.31;
    vec2 id = floor(q); vec2 f = fract(q) - 0.5;
    float h = hash12(id + float(k) * 3.7);
    float ph = fract(uTime * (1.1 + h * 0.8) + h * 7.0);
    vec2 c = (vec2(hash12(id + 1.3), hash12(id + 7.1)) - 0.5) * 0.45;
    vec2 d = f - c; float r = length(d);
    float R = ph * 0.42, w = (1.0 - ph) * (1.0 - ph);
    float x = (r - R) * 26.0;
    acc += d / max(r, 1e-3) * (sin(x * 1.6) * exp(-x * x * 0.35)) * w;
  }
  return acc;
}

// river centre-line lookup (x, halfWidth) — z range matches world.js RZ0..RZ1
vec3 riverAt(float z){ return texture2D(uRiverTex, vec2(clamp((z + 1600.0) / 2020.0, 0.0, 1.0), 0.5)).xyz; }

// one shared wind field: slow gust fronts travelling along the wind direction
float windGust(vec3 wp){
  vec2 d = uWind.xy;
  float along = dot(wp.xz, d);
  float g = 0.55 + 0.45 * sin(uTime * 0.55 - along * 0.045) * (0.6 + 0.4 * sin(uTime * 0.21 + wp.x * 0.013 - wp.z * 0.011));
  return max(g, 0.08) * uWind.z;
}
vec3 windSway(vec3 wp, float flex, float phase){
  float g = windGust(wp);
  float t = uTime;
  float s = sin(t * 1.35 + phase + dot(wp.xz, uWind.xy) * 0.09) * 0.55 + sin(t * 2.3 + phase * 1.9) * 0.22;
  vec3 dir = vec3(uWind.x, 0.0, uWind.y);
  vec3 side = vec3(-uWind.y, 0.0, uWind.x);
  return (dir * (0.55 + s) * g + side * sin(t * 1.7 + phase * 2.3) * 0.18 * g) * flex;
}

vec3 skyFogColor(vec3 rd){
  float s = max(dot(rd, uSunDir), 0.0);
  float warm = clamp(pow(s, 2.5) * 0.95 + 0.06, 0.0, 1.0);
  vec3 c = mix(uFogCool, uFogWarm, warm);
  c += uSunCol * (pow(s, 12.0) * 0.07 + pow(s, 90.0) * 0.18) * (1.0 - uStorm * 0.85);
  // lightning lights the rain and haze from inside
  c += vec3(0.5, 0.58, 0.8) * uFlash * (0.05 + 0.45 * pow(max(dot(rd, uFlashDir), 0.0), 4.0));
  return c;
}

// Aerial perspective: analytic exponential height fog + haze + drifting river mist, in-scattered sun
vec3 applyAtmosphere(vec3 col, vec3 wp){
  vec3 ro = cameraPosition;
  if (uReflect > 0.5) ro.y = -ro.y;
  vec3 dv = wp - ro;
  float dist = length(dv);
  vec3 rd = dv / max(dist, 1e-3);
  float fall = uFogParams.y;
  float k = fall * dv.y;
  float fh = uFogParams.x * exp(-fall * (ro.y - uFogParams.z)) * dist * (abs(k) > 1e-3 ? (1.0 - exp(-k)) / k : 1.0);
  // river mist: thin layer hugging the water, breaking into drifting banks
  float my = clamp(1.0 - wp.y / 7.0, 0.0, 1.0);
  vec2 mp = wp.xz * 0.035 + vec2(uTime * 0.05, uTime * 0.07);
  float mn = vnoise(mp) * 1.3 - 0.35;
  float mist = uMist * my * my * max(mn + uStorm * 0.25, 0.0) * min(dist, 140.0) * 0.0042;
  float haze = uFogParams.w * dist;
  float T = exp(-(fh + haze + mist));
  vec3 fc = skyFogColor(normalize(vec3(rd.x, max(rd.y, -0.05), rd.z)));
  // mist glows warm where the sun rakes through it
  fc += uSunCol * 0.04 * mist * pow(max(dot(rd, uSunDir), 0.0), 3.0);
  vec3 outc = col * T + fc * (1.0 - T);
  // the submerged bed is seen through the water surface, which applies the air's haze itself:
  // fogging it here as well doubled the (sunlit) mist and the water tinted it a glowing green
  if (uReflect < 0.5 && wp.y < 0.0 && ro.y > 0.0) outc = mix(col, outc, smoothstep(-0.3, 0.0, wp.y));
  return outc;
}

      attribute float aVariant;
      varying vec2 vUv; varying vec3 vN; varying vec3 vWP; varying float vH; varying vec3 vTint;
      void main(){
        vec3 p = position;
        vec4 wp0 = modelMatrix * instanceMatrix * vec4(p, 1.0);
        p.xz += windSway(wp0.xyz, 0.02, aVariant * 3.0).xz * p.y * p.y * 1.5;
        vec4 wp = modelMatrix * instanceMatrix * vec4(p, 1.0);
        vUv = vec2(uv.x + aVariant * 0.25, uv.y);
        vN = normalize(mat3(modelMatrix * instanceMatrix) * normal);
        vH = position.y; vWP = wp.xyz;
        vTint = vec3(1.0);
        #ifdef USE_INSTANCING_COLOR
          vTint = instanceColor;
        #endif
        gl_Position = projectionMatrix * viewMatrix * wp;
      }

